import forgelib as F
G = F.make(slug="the-forge-volcanic-depths", order=14, kw="volcanic depths",
 title="How to Get to Volcanic Depths in The Forge (+ Farming)",
 h1="How to Get to the Volcanic Depths in The Forge and Farm Darkryte and Demonite",
 desc="How to get to the Volcanic Depths in The Forge step by step, the pickaxe you need, the best way to farm Volcanic Rocks, and Darkryte and Demonite odds.",
 kw2=["the forge volcanic depths","how to get to volcanic depths the forge","the forge darkryte","the forge demonite","the forge volcanic rock"],
 related=["the-forge-forging-guide","the-forge-armor-guide","the-forge-money-guide","the-forge-pickaxe-progression"],
 ids=["SVb-UKmj5eM","G3srORSAIxY"],
 lead="The <strong>Volcanic Depths</strong> is the high-level lava zone under the Forgotten Kingdom, and it's home to Darkryte and Demonite. Fridge has a video on getting there and another on farming Volcanic Rocks. Here's the route and the current drop rates.",
 heading="Watch Fridge's Volcanic Depths Videos",
 sections=[
 ("route","How to Get to the Volcanic Depths","""<ol class="steps"><li>Teleport to the <strong>Forgotten Kingdom</strong> (Island 2, level 10).</li><li>Head into the <strong>Ruined Cave</strong>. The Cannon near spawn launches you to its entrance.</li><li>Inside, take the <strong>right-hand path</strong> marked by a wooden <strong>DANGER</strong> sign, into the Ashen Passage.</li><li>Keep to the right wall until you reach the orange, spiky rocks near <strong>Amber</strong>, who stands by the Magma Pickaxe.</li><li>Break the two <strong>Basalt Veins</strong> blocking a hole in the floor. Gamezebo puts them at about 2,750 HP.</li><li>Drop down the hole into the Volcanic Depths.</li></ol>
<p class="small">This route was checked against Gamezebo and Pro Game Guides, and the area names match the Forge Wiki.</p>"""),
 ("dangers","What's Down There","""<p>The Forge Wiki calls it a high-level zone full of lava pools, magma walls and volcanic versions of enemies. Watch out for the <strong>Reaper</strong>, which drops the Drain Edge rune, the <strong>Elite Deathaxe Skeleton</strong> and the <strong>Blight Pyromancer</strong>. Use block and parry, covered in our <a href="the-forge-combat-guide.html">combat guide</a>. At the far back is <strong>Skal</strong>, the demon in Demon's Hideout. Bring him 3 Demonite for the Demonite Key, which opens the gate to the <strong>Demonic Pickaxe</strong> (200 Mine Power, +53% Luck).</p>"""),
 ("rocks","Farming Volcanic Rocks","""<div class="table-wrap"><table><caption>Volcanic Rock (Forge Wiki)</caption><thead><tr><th scope="col">Stat</th><th scope="col">Value</th></tr></thead><tbody>
<tr><td>Health</td><td>3,680 (the highest on the island)</td></tr><tr><td>Required damage</td><td>100 Mine Power</td></tr><tr><td>Ores per rock</td><td>3–4</td></tr><tr><td>Luck multiplier</td><td>9x</td></tr><tr><td>XP</td><td>45</td></tr></tbody></table></div>
<p>Drops include Topaz, Cuprite, Rivalite, Obsidian, Eye Ore, Fireite, Magmaite, <strong>Demonite</strong> and <strong>Darkryte</strong>. For speed, use a pickaxe well above 100 Mine Power, rune it for Swift Mining and Mine Power, and drink a Luck Potion during a Fortune event.</p>"""),
 ("ores","Darkryte and Demonite","""<ul><li><strong>Demonite</strong> (Mythic): about a 1 in 3,666 chance, 5.5x multiplier. On armor, it adds Burn and Backfire. You can also craft it from 1 Magmaite, 1 Uranium and 1 Fireite for 500 Gold.</li><li><strong>Darkryte</strong> (Mythic): about a 1 in 6,655 chance, 6.3x multiplier. On armor, it gives a 15% Phantom Step dodge. You can craft it from 1 Demonite and 1 Magmaite for 500 Gold.</li></ul>
<p>The crafting recipes mean you don't have to rely only on lucky drops. Turn them into armor with our <a href="the-forge-armor-guide.html">armor guide</a>. Keep at least 1 Demonite for the Ice Man's quest on Island 3.</p>""")],
 faq=[("How do you get to the Volcanic Depths in The Forge?","In the Forgotten Kingdom's Ruined Cave, follow the DANGER sign to the right, break the two Basalt Veins near Amber, and drop down the hole."),
      ("What pickaxe do you need for Volcanic Rocks?","At least 100 Mine Power, according to the Forge Wiki."),
      ("What is the Darkryte drop chance in The Forge?","About 1 in 6,655 from Volcanic Rocks. You can also craft it from Demonite and Magmaite.")],
 sources=[F.wiki("Volcanic_Rock","Volcanic Rock"),F.wiki("Darkryte"),F.wiki("Demonite"),F.wiki("Forgotten_Kingdom","Forgotten Kingdom"),F.wiki("Demonic_Pickaxe","Demonic Pickaxe"),("Gamezebo: How to get to the Volcanic Depths","https://www.gamezebo.com/walkthroughs/how-to-get-to-the-volcanic-depths-in-the-forge/"),("Pro Game Guides: Forgotten Kingdom map","https://progameguides.com/roblox/the-forge-map-all-islands-locations-level-requirements/")],
 howto=("How to get to the Volcanic Depths in The Forge",[("Go to the Ruined Cave","Teleport to the Forgotten Kingdom and enter the Ruined Cave.","route"),("Follow the DANGER sign","Take the right path into the Ashen Passage.","route"),("Break the Basalt Veins","Mine the two veins blocking the hole near Amber.","route"),("Drop down","Jump into the hole to reach the Volcanic Depths.","route")]))
